<?php
require_once __DIR__.'/Caja.php';
require_once __DIR__.'/Producto.php';
class Credito
{
    private $db;
    public function __construct(PDO $db){$this->db=$db;}
    public static function saldoSql($alias='c'){return "GREATEST(0,".$alias.".monto_original-COALESCE((SELECT SUM(a.monto) FROM abonos_cliente a WHERE a.venta_id=".$alias.".venta_id),0)-COALESCE((SELECT SUM(p.monto) FROM pagos_devolucion p JOIN devoluciones_venta d ON d.id=p.devolucion_id WHERE d.venta_id=".$alias.".venta_id AND p.tipo_metodo='credito'),0))";}
    public function disponible($id,$lock=false){
        $q=$this->db->prepare('SELECT id,nombre,activo FROM clientes WHERE id=?'.($lock?' FOR UPDATE':''));$q->execute(array($id));$client=$q->fetch();if(!$client)throw new HttpError('Cliente no encontrado.',404);
        $q=$this->db->prepare('SELECT cliente_id,habilitado,limite,dias FROM configuracion_credito_cliente WHERE cliente_id=?');$q->execute(array($id));$cfg=$q->fetch()?:array('cliente_id'=>$id,'habilitado'=>0,'limite'=>'0.00','dias'=>30);
        $q=$this->db->prepare('SELECT CAST(COALESCE(SUM('.self::saldoSql().'),0) AS DECIMAL(14,2)) FROM creditos_venta c WHERE c.cliente_id=?');$q->execute(array($id));$cfg['saldo']=$q->fetchColumn();$cfg['disponible']=Caja::dinero(max(0,Caja::centavos($cfg['limite'])-Caja::centavos($cfg['saldo'])));$cfg['nombre']=$client['nombre'];$cfg['activo']=$client['activo'];$cfg['version']=hash('sha256',json_encode($cfg));return $cfg;
    }
    public function configurar($id,array $d,$actorId){
        $limit=Caja::centavos(isset($d['limite'])?$d['limite']:null);$enabled=isset($d['habilitado'])?$d['habilitado']:null;$days=isset($d['dias'])?$d['dias']:null;if(!in_array($enabled,array(0,1,'0','1',false,true),true)||!is_scalar($days)||!preg_match('/^[1-9][0-9]{0,2}$/D',(string)$days)||$days>365)throw new HttpError('Selecciona un plazo de 1 a 365 días y un estado válido.');if($enabled&&!$limit)throw new HttpError('Configura un límite mayor que cero para habilitar el crédito.');
        $this->db->exec('SET TRANSACTION ISOLATION LEVEL READ COMMITTED');$this->db->beginTransaction();try{
            $this->actor($actorId,'todo');$current=$this->disponible($id,true);if(!isset($d['version'])||!is_string($d['version'])||!hash_equals($current['version'],$d['version']))throw new HttpError('El saldo o la configuración cambiaron. Vuelve a consultar el cliente.',409);
            $q=$this->db->prepare('SELECT cliente_predeterminado_id FROM configuracion_clientes WHERE id=1');$q->execute();if($enabled&&((string)$q->fetchColumn()===(string)$id||!$current['activo']))throw new HttpError('El crédito requiere un cliente activo que no sea el predeterminado.');
            if($limit<Caja::centavos($current['saldo']))throw new HttpError('El límite no puede ser menor que la deuda actual.');
            $this->db->prepare('INSERT INTO configuracion_credito_cliente(cliente_id,habilitado,limite,dias) VALUES (?,?,?,?) ON DUPLICATE KEY UPDATE habilitado=VALUES(habilitado),limite=VALUES(limite),dias=VALUES(dias)')->execute(array($id,(int)$enabled,Caja::dinero($limit),(int)$days));$this->db->commit();return array('cliente_id'=>$id);
        }catch(Throwable $e){if($this->db->inTransaction())$this->db->rollBack();throw $e;}
    }
    private function actor($id,$permiso){
        $this->db->query('SELECT id FROM roles ORDER BY id FOR SHARE')->fetchAll();$q=$this->db->prepare('SELECT id FROM usuarios WHERE id=? FOR UPDATE');$q->execute(array($id));$q->fetchColumn();$a=(new Usuario($this->db))->buscar($id);if(!$a||!$a['activo']||(empty($a['permisos']['todo'])&&(empty($a['permisos'][$permiso])||($permiso==='cobrar_abonos'&&(empty($a['permisos']['operar_caja'])||empty($a['permisos']['ver_creditos']))))))throw new HttpError('No tienes permiso para esta operación.',403);return $a;
    }
    public function clientes(array $f){$s=Producto::texto($f,'buscar',100,false);$q=$this->db->prepare("SELECT id,nombre,activo FROM clientes WHERE nombre LIKE ? ESCAPE '!' ORDER BY nombre,id LIMIT 30");$q->execute(array('%'.str_replace(array('!','%','_'),array('!!','!%','!_'),$s).'%'));return $q->fetchAll();}
    public function listar(array $f,array $actor){
        $where='1=1';$args=array();if(empty($actor['permisos']['todo'])){$where.=' AND v.usuario_id=?';$args[]=$actor['id'];}
        $search=Producto::texto($f,'buscar',100,false);if($search!==''){$where.=" AND (v.folio LIKE ? ESCAPE '!' OR cl.nombre LIKE ? ESCAPE '!')";$s='%'.str_replace(array('!','%','_'),array('!!','!%','!_'),$search).'%';$args[]=$s;$args[]=$s;}
        $estado=isset($f['estado'])?$f['estado']:'pendiente';if(!in_array($estado,array('pendiente','todos'),true))throw new HttpError('Selecciona un estado válido.');if($estado==='pendiente')$where.=' AND '.self::saldoSql().'>0';
        if(isset($f['antes_de'])&&$f['antes_de']!==''){$where.=' AND c.venta_id<?';$args[]=Producto::identificador($f['antes_de']);}
        $rows=$this->consultar('SELECT c.venta_id,c.cliente_id,v.folio,cl.nombre cliente,c.monto_original,c.vence,CAST('.self::saldoSql().' AS DECIMAL(14,2)) saldo FROM creditos_venta c JOIN ventas v ON v.id=c.venta_id JOIN clientes cl ON cl.id=c.cliente_id WHERE '.$where.' ORDER BY c.venta_id DESC LIMIT 31',$args);$more=count($rows)>30;if($more)array_pop($rows);return array('creditos'=>$rows,'siguiente'=>$more?$rows[count($rows)-1]['venta_id']:null,'todos'=>!empty($actor['permisos']['todo']));
    }
    private function consultar($sql,array $args){$q=$this->db->prepare($sql);$q->execute($args);return $q->fetchAll();}
    private function prestamo($id,array $actor,$lock=false){
        $q=$this->db->prepare('SELECT v.id,v.folio,v.usuario_id,v.cliente_id,v.estatus,c.monto_original,c.vence,cl.nombre cliente FROM ventas v JOIN creditos_venta c ON c.venta_id=v.id JOIN clientes cl ON cl.id=v.cliente_id WHERE v.id=?'.($lock?' FOR UPDATE':''));$q->execute(array($id));$r=$q->fetch();if(!$r)throw new HttpError('Crédito no encontrado.',404);if(empty($actor['permisos']['todo'])&&(string)$r['usuario_id']!==(string)$actor['id'])throw new HttpError('Solo puedes consultar créditos de tus propias ventas.',403);return $r;
    }
    public function obtener($id,array $actor){
        $this->db->exec('SET TRANSACTION ISOLATION LEVEL READ COMMITTED');$this->db->beginTransaction();try{$r=$this->prestamo($id,$actor);$q=$this->db->prepare('SELECT CAST('.self::saldoSql().' AS DECIMAL(14,2)) FROM creditos_venta c WHERE c.venta_id=?');$q->execute(array($id));$r['saldo']=$q->fetchColumn();$r['abonos']=$this->consultar('SELECT id,folio,monto,recibido,cambio,referencia,datos,UNIX_TIMESTAMP(creado_en) creado_unix FROM abonos_cliente WHERE venta_id=? ORDER BY id DESC',array($id));foreach($r['abonos'] as &$a){$data=json_decode($a['datos'],true);$a['usuario']=$data['usuario'];$a['metodo']=$data['metodo'];$a['caja']=$data['caja'];$a['cliente']=$data['cliente'];$a['venta_folio']=$data['venta_folio'];unset($a['datos']);}unset($a);
            $r['ajustes']=$this->consultar("SELECT d.folio,p.nombre_metodo,p.tipo_metodo,p.monto,UNIX_TIMESTAMP(d.creado_en) creado_unix FROM pagos_devolucion p JOIN devoluciones_venta d ON d.id=p.devolucion_id WHERE d.venta_id=? ORDER BY p.id DESC",array($id));
            $r['turnos']=$this->consultar("SELECT t.id,c.nombre caja FROM turnos_caja t JOIN cajas c ON c.id=t.caja_id JOIN ubicaciones l ON l.id=COALESCE(t.ubicacion_id,c.ubicacion_id) WHERE t.abierto_por=? AND t.estatus='abierto' AND c.activo=1 AND l.activo=1 AND l.disponible_venta=1",array($actor['id']));$r['metodos']=$this->db->query("SELECT id,nombre,tipo FROM metodos_pago WHERE activo=1 AND tipo<>'credito' ORDER BY id")->fetchAll();$r['puede_abonar']=!empty($actor['permisos']['todo'])||(!empty($actor['permisos']['cobrar_abonos'])&&!empty($actor['permisos']['operar_caja']));$this->db->commit();return $r;
        }catch(Throwable $e){if($this->db->inTransaction())$this->db->rollBack();throw $e;}
    }
    public function abonar($id,array $d,$actorId){
        $turn=Producto::identificador(isset($d['turno_id'])?$d['turno_id']:null);$method=Producto::identificador(isset($d['metodo_pago_id'])?$d['metodo_pago_id']:null);$n=Caja::centavos(isset($d['monto'])?$d['monto']:null);if(!$n)throw new HttpError('El abono debe ser mayor que cero.');$received=isset($d['recibido'])&&$d['recibido']!==''?Caja::centavos($d['recibido']):null;$ref=Producto::texto($d,'referencia',100,false);$key=isset($d['clave'])?$d['clave']:'';if(!is_string($key)||!preg_match('/^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$/D',$key))throw new HttpError('Recarga el formulario del abono.');$hash=hash('sha256',json_encode(array((string)$id,$turn,$method,$n,$received,$ref)));$this->db->exec('SET TRANSACTION ISOLATION LEVEL READ COMMITTED');$this->db->beginTransaction();
        try{$actor=$this->actor($actorId,'cobrar_abonos');$q=$this->db->prepare('SELECT id,huella,folio,monto FROM abonos_cliente WHERE usuario_id=? AND clave=?');$q->execute(array($actorId,$key));$old=$q->fetch();if($old){if(!hash_equals($old['huella'],$hash))throw new HttpError('La solicitud ya se utilizó con otros datos.',409);$this->db->commit();return array('abono_id'=>$old['id'],'folio'=>$old['folio'],'monto'=>$old['monto']);}
            $q=$this->db->prepare('SELECT caja_id,turno_id FROM ventas WHERE id=?');$q->execute(array($id));$original=$q->fetch();if(!$original)throw new HttpError('Venta no encontrada.',404);$q=$this->db->prepare('SELECT caja_id FROM turnos_caja WHERE id=?');$q->execute(array($turn));$box=$q->fetchColumn();if(!$box)throw new HttpError('Turno no encontrado.',404);
            $boxes=array_values(array_unique(array($box,$original['caja_id'])));sort($boxes,SORT_NUMERIC);$q=$this->db->prepare('SELECT id FROM cajas WHERE id IN ('.implode(',',array_fill(0,count($boxes),'?')).') ORDER BY id FOR UPDATE');$q->execute($boxes);$q->fetchAll();$ids=array_values(array_unique(array($turn,$original['turno_id'])));sort($ids,SORT_NUMERIC);$q=$this->db->prepare('SELECT id FROM turnos_caja WHERE id IN ('.implode(',',array_fill(0,count($ids),'?')).') ORDER BY id FOR UPDATE');$q->execute($ids);$q->fetchAll();
            $q=$this->db->prepare("SELECT t.*,c.nombre caja,l.nombre ubicacion FROM turnos_caja t JOIN cajas c ON c.id=t.caja_id JOIN ubicaciones l ON l.id=COALESCE(t.ubicacion_id,c.ubicacion_id) WHERE t.id=? AND t.estatus='abierto' AND c.activo=1 AND l.activo=1 AND l.disponible_venta=1");$q->execute(array($turn));$t=$q->fetch();if(!$t||(string)$t['abierto_por']!==(string)$actorId)throw new HttpError('Registra el abono en tu propia caja abierta.',403);
            $loan=$this->prestamo($id,$actor,true);$this->disponible($loan['cliente_id'],true);$q=$this->db->prepare('SELECT '.self::saldoSql().' FROM creditos_venta c WHERE c.venta_id=?');$q->execute(array($id));$balance=Caja::centavos($q->fetchColumn());if($n>$balance||$loan['estatus']!=='completada')throw new HttpError('El abono supera el saldo pendiente. Actualiza el crédito.',409);
            $q=$this->db->prepare('SELECT id,nombre,tipo,activo FROM metodos_pago WHERE id=? FOR SHARE');$q->execute(array($method));$m=$q->fetch();if(!$m||!$m['activo']||$m['tipo']==='credito')throw new HttpError('Selecciona un método activo que no sea crédito.');$change=0;if($m['tipo']==='efectivo'){$received=$received===null?$n:$received;if($received<$n)throw new HttpError('El efectivo recibido no cubre el abono.');$change=$received-$n;$cash=(new Caja($this->db))->resumenBloqueado($t);if(Caja::centavos($cash['esperado'],true)+$n>Caja::MAXIMO)throw new HttpError('El abono supera el límite de efectivo de la caja.');}elseif($received!==null)throw new HttpError('Recibido solo se usa para efectivo.');
            $snapshot=array('usuario'=>$actor['nombre'],'metodo'=>$m['nombre'],'caja'=>$t['caja'],'cliente'=>$loan['cliente'],'venta_folio'=>$loan['folio']);$this->db->prepare('INSERT INTO abonos_cliente(folio,venta_id,cliente_id,turno_id,usuario_id,metodo_pago_id,monto,recibido,cambio,referencia,clave,huella,datos) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?)')->execute(array('P-'.bin2hex(random_bytes(10)),$id,$loan['cliente_id'],$turn,$actorId,$method,Caja::dinero($n),$received===null?null:Caja::dinero($received),Caja::dinero($change),$ref,$key,$hash,json_encode($snapshot)));$abono=$this->db->lastInsertId();$folio='A-'.str_pad($abono,8,'0',STR_PAD_LEFT);$this->db->prepare('UPDATE abonos_cliente SET folio=? WHERE id=?')->execute(array($folio,$abono));
            $this->db->prepare('INSERT INTO pagos_venta(venta_id,metodo_pago_id,monto,recibido,cambio,referencia,tipo_metodo,nombre_metodo,abono_id) VALUES (?,?,?,?,?,?,?,?,?)')->execute(array($id,$method,Caja::dinero($n),$received===null?null:Caja::dinero($received),Caja::dinero($change),$ref,$m['tipo'],$m['nombre'],$abono));$this->db->commit();return array('abono_id'=>$abono,'folio'=>$folio,'monto'=>Caja::dinero($n));
        }catch(Throwable $e){if($this->db->inTransaction())$this->db->rollBack();throw $e;}
    }
}
